	.include	"inc/falcon.inc"

; base routines these patches call (unnamed in the decompilation):
	FUN_CODE_29f2 = 0x29f2

;==============================================================================
; CR4: Team Xecuter CR4 (RGH2+): HANA I2C slowdown driven from the 1 ms IRQ, infinite boot retries, debug LED repurposed
; reproduces: FALCON_CR4
; SMC_PLUS (two-byte hexedit on top of CR4): shorten the reset-watchdog boot timeout
; The 1 ms IRQ (via the hooked anl at 0x0156) calls cr4_slowdown_update, which
; watches DBG_LED0 and SFR 0BAh (abused as the slowdown-state cell) and toggles
; HANA register 0xCD: enable = 4E 08 80 03, default = 4E 80 0C 02. The register is
; set by faking a commandlist transfer at offset 0. Boot-try increment is NOPed
; (infinite retries) and the DBG_LED0 state machine is disabled.
;==============================================================================
	.ifdef	CR4

;------------------------------------------------------------------------------
; 0x0156-0x0158  (3 bytes)  in outside any function in the base
;   was: anl sfr_pcie_status_dpsel, #0xfd
;------------------------------------------------------------------------------
	SMCPATCH 0x0156
	lcall	cr4_slowdown_update		; 0x0156

;------------------------------------------------------------------------------
; 0x0756-0x0758  (3 bytes)  in outside any function in the base
;   was: mov SP, #0xb8
;------------------------------------------------------------------------------
	SMCPATCH 0x0756
	mov	SP, #0xba		; 0x0756

;------------------------------------------------------------------------------
; 0x0775-0x0777  (3 bytes)  in mainloop
;   was: mov SP, #0xb8
;------------------------------------------------------------------------------
	SMCPATCH 0x0775
	mov	SP, #0xba		; 0x0775

;------------------------------------------------------------------------------
; 0x07c2-0x07c4  (3 bytes)  in mainloop
;   was: lcall dbgled_sm_exec
;------------------------------------------------------------------------------
	SMCPATCH 0x07c2
	nop		; 0x07c2
	nop		; 0x07c3
	nop		; 0x07c4

;------------------------------------------------------------------------------
; 0x12a3-0x12a4  (2 bytes)  in sysreset_watchdog_statemachine_exec
;   was: inc g_num_boot_tries
;------------------------------------------------------------------------------
	SMCPATCH 0x12a3
	nop		; 0x12a3
	nop		; 0x12a4

;------------------------------------------------------------------------------
; 0x13c3-0x13ea  (40 bytes)  in dbgled_sm_exec
;   was: mov a, g_boot_status_blink_pattern
;   was: anl a, g_dbgled_blinkpattern_andmask
;   was: jnz 0x13ce
;   was: lcall dbg_led_off
;   was: sjmp 0x13d1
;   was: lcall dbg_led_on
;   was: mov a, g_boot_attempt_blink_pattern
;   was: anl a, g_dbgled_blinkpattern_andmask
;   was: jnz 0x13dc
;   was: lcall stubbedout_xenon_dbgled1_clear
;   ... (8 more)
;------------------------------------------------------------------------------
	SMCPATCH 0x13c3
	; repurposed dbgled_sm_exec_state_0: build+send HANA 0xCD slowdown-ENABLE (4E 08 80 03)
	mov	0x1a, #0xcd		; 0x13c3
	mov	0x19, #0x04		; 0x13c6
	mov	0x18, #0x4e		; 0x13c9
	mov	0x17, #0x08		; 0x13cc
	mov	0x16, #0x80		; 0x13cf
	mov	0x15, #0x03		; 0x13d2
	ret		; 0x13d5
cr4_hana_slowdown_default:
	mov	0x1a, #0xcd		; 0x13d6
	mov	0x19, #0x04		; 0x13d9
	mov	0x18, #0x4e		; 0x13dc
	mov	0x17, #0x80		; 0x13df
	mov	0x16, #0x0c		; 0x13e2
	mov	0x15, #0x02		; 0x13e5
	ljmp	cr4_commit_i2c_write		; 0x13e8

;------------------------------------------------------------------------------
; 0x230c-0x230e  (3 bytes)  in FUN_CODE_22be
;   was: mov HPINDEX, #0xff
;------------------------------------------------------------------------------
	SMCPATCH 0x230c
	ljmp	cr4_slowdown_init		; 0x230c

;------------------------------------------------------------------------------
; 0x237c-0x237e  (3 bytes)  in gpios_reset
;   was: mov sfr_ddr_port3, #0xf6
;------------------------------------------------------------------------------
	SMCPATCH 0x237c
	mov	sfr_ddr_port3, #0xf7		; 0x237c

;------------------------------------------------------------------------------
; 0x2d03-0x2d72  (112 bytes)  in outside any function in the base
;   was: 0x00 x 112 (not code in the base)
;------------------------------------------------------------------------------
	SMCPATCH 0x2d03
cr4_slowdown_enable:
	lcall	dbgled_sm_exec_state_0		; 0x2d03
	sjmp	cr4_commit_i2c_write		; 0x2d06
cr4_wait_i2c_idle:
	lcall	watchdog_kick		; 0x2d08
	jb	0x60, cr4_wait_i2c_idle		; 0x2d0b
	ret		; 0x2d0e
cr4_commit_i2c_write:
	lcall	cr4_wait_i2c_idle		; 0x2d0f
	lcall	cr4_i2c_reset_and_kickoff		; 0x2d12
	ret		; 0x2d15
cr4_slowdown_update:
	mov	r1, 0xba		; 0x2d16
	mov	c, gpio_dbg_led0		; 0x2d18
	jc	p_2d27		; 0x2d1a
	cjne	r1, #0x02, cr4_update_store_state		; 0x2d1c
	lcall	cr4_hana_slowdown_default		; 0x2d1f
	mov	r1, #0x01		; 0x2d22
	ljmp	cr4_update_store_state		; 0x2d24
p_2d27:
	cjne	r1, #0x01, cr4_update_store_state		; 0x2d27
	lcall	cr4_slowdown_enable		; 0x2d2a
	mov	r1, #0x02		; 0x2d2d
cr4_update_store_state:
	mov	0xba, r1		; 0x2d2f
	anl	sfr_pcie_status_dpsel, #0xfd		; 0x2d31
	ret		; 0x2d34
	; init hook (reached from the hooked mov HPINDEX at 0x230c): force slowdown state = 1
cr4_slowdown_init:
	mov	r1, #0x01		; 0x2d35
	mov	0xba, r1		; 0x2d37
	mov	HPINDEX, #0xff		; 0x2d39
	ret		; 0x2d3c
cr4_i2c_reset_and_kickoff:
	lcall	cr4_wait_i2c_idle		; 0x2d3d
	lcall	i2c_reset_buses		; 0x2d40
	lcall	i2c_read_bit		; 0x2d43
	jnc	p_2d54		; 0x2d46
	lcall	FUN_CODE_29f2		; 0x2d48
	jnc	p_2d54		; 0x2d4b
	setb	F0		; 0x2d4d
	lcall	i2c_reset_buses		; 0x2d4f
	setb	c		; 0x2d52
	ret		; 0x2d53
p_2d54:
	clr	gpio_smb_data		; 0x2d54
	lcall	i2c_burn_cycles		; 0x2d56
	setb	gpio_smb_data		; 0x2d59
	lcall	i2c_burn_cycles		; 0x2d5b
	lcall	i2c_handover_bus		; 0x2d5e
	setb	g_i2c_operation_pending		; 0x2d61
	mov	0x11, #0xe0		; 0x2d63
	mov	0x12, #0x06		; 0x2d66
	clr	0x5e		; 0x2d69
	clr	g_i2c_read_pending		; 0x2d6b
	clr	g_i2c_is_ipc_operation		; 0x2d6d
	lcall	i2c_yield_to_async_operation		; 0x2d6f
	ret		; 0x2d72

